import sys
from itertools import permutations
MOD = 998244353

data = sys.stdin.read().split()
n = int(data[0])
marks = data[1]
if n <= 8:
    cnt = 0
    for perm in permutations(range(1, n + 1)):
        ok = True
        for i, ch in enumerate(marks):
            if ch == "<" and perm[i] > perm[i + 1]:
                ok = False
                break
            if ch == ">" and perm[i] < perm[i + 1]:
                ok = False
                break
        if ok:
            cnt += 1
    print(cnt % MOD)
else:
    # flipping every mark maps each chain to the chain of complements, so the count is unchanged
    flip = {"<": ">", ">": "<", "?": "?"}
    dp = [1]
    for ch0 in marks:
        ch = flip[ch0]
        pref = [0] * (len(dp) + 1)
        run = 0
        for idx, value in enumerate(dp):
            run = (run + value) % MOD
            pref[idx + 1] = run
        if ch == "<":
            dp = pref
        elif ch == ">":
            dp = [(run - x) % MOD for x in pref]
        else:
            dp = [run] * len(pref)
    print(sum(dp) % MOD)
